<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('network','edit');global $conn;$tenantId=(int)getCurrentTenantId();$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM network_sites WHERE id=? AND tenant_id=?");$q->bind_param('ii',$id,$tenantId);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();if(!$row){http_response_code(404);exit('Network site not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');$location=trim($_POST['location']??'');$status=$_POST['status']??'active';$description=trim($_POST['description']??'');if($name==='')$error='Site name is required.';else{$q=$conn->prepare("UPDATE network_sites SET name=?,location=?,status=?,description=? WHERE id=? AND tenant_id=?");$q->bind_param('ssssii',$name,$location,$status,$description,$id,$tenantId);if($q->execute())redirect('index.php');$error=$q->error?:'Unable to update site.';$q->close();}}
$pageTitle='Edit Network Site';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Edit Network Site</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Name</label><input name="name" required value="<?=e($row['name'])?>"></div><div class="form-group"><label>Location</label><input name="location" value="<?=e($row['location'])?>"></div><div class="form-group"><label>Status</label><select name="status"><option value="active" <?=$row['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$row['status']!=='active'?'selected':''?>>Inactive</option></select></div><div class="form-group"><label>Description</label><textarea name="description"><?=e($row['description'])?></textarea></div><button type="submit">Update Site</button> <a href="index.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>